// =============================================================
// UNYX · Verificar Cliente — Nodo "Acceso Denegado"
// Salida de descarte del Switch Cliente: el token del widget no coincide con
// el de ningún cliente configurado.
// =============================================================
return [{
  json: {
    ok: false,
    message: 'Acceso no autorizado. Revise el token del widget o contacte al administrador.',
  },
}];

// =============================================================
// UNYX · Verificar Cliente — Nodo "Cuenta Incorrecta"
//
// El token corresponde a este cliente, pero el widget está instalado en otra
// cuenta de Kommo (o mal configurado). Se corta aquí: si siguiera, el asesor
// vería datos y crearía leads en la cuenta equivocada con este token.
// =============================================================
return [{
  json: {
    ok: false,
    message: 'El token no corresponde a esta cuenta de Kommo. Revise la configuración del widget.',
  },
}];

// =============================================================
// UNYX · Verificar Cliente — Nodo "Teléfono Inválido"
// Se responde 200 con ok:false para que el widget muestre el mensaje
// exacto en lugar del error genérico de red.
// =============================================================
return [{
  json: {
    ok: false,
    message: 'Ingrese 9 dígitos y seleccione un celular válido.',
  },
}];

// =============================================================
// UNYX · Verificar Cliente — Nodo "Preparar Consultas"
// Normaliza el celular ecuatoriano y genera una consulta por variante.
// El payload viene del webhook (cuerpo de formulario de self.crm_post o JSON).
// =============================================================
const body = $json.body || $json;

const digits = String(body.phone || '').replace(/\D/g, '');
let local = digits;
if (local.startsWith('593')) local = local.slice(3);
if (local.startsWith('0')) local = local.slice(1);

if (!/^9\d{8}$/.test(local)) {
  throw new Error('Teléfono inválido: se esperaban 9 dígitos de celular ecuatoriano.');
}

const phone = '+593' + local;
const userId = parseInt(body.userId || 0, 10) || 0;
const userName = String(body.userName || '').trim();

// Kommo busca por texto libre sobre los campos personalizados: se consultan
// las tres formas habituales de guardar el número y luego se compara exacto.
const variants = [local, '0' + local, phone];

return variants.map((variant) => ({
  json: { variant, phone, local, userId, userName },
}));

// =============================================================
// UNYX · Verificar Cliente — Nodo "Unificar Contactos"
// Recibe la respuesta de cada variante, deduplica por id y descarta los
// contactos cuyo teléfono no coincide exactamente con el buscado.
// Recoge también los ids de los leads enlazados (with=leads).
// =============================================================
const first = $('Meditec · Preparar Consultas').first().json;
const target = first.local;

function digitsOf(value) {
  return String(value === null || value === undefined ? '' : value).replace(/\D/g, '');
}

function phonesMatch(value) {
  let candidate = digitsOf(value);
  if (!candidate || candidate.length < 7 || candidate.length > 15) return false;
  if (candidate.startsWith('593')) candidate = candidate.slice(3);
  if (candidate.startsWith('0')) candidate = candidate.slice(1);
  return candidate === target;
}

const contactsById = new Map();

for (const item of $input.all()) {
  const contacts = item.json?._embedded?.contacts ?? [];
  for (const contact of contacts) {
    if (!contact || contact.is_deleted) continue;
    const phones = [];
    for (const field of contact.custom_fields_values ?? []) {
      for (const entry of field.values ?? []) {
        if (entry && entry.value !== undefined && entry.value !== null) phones.push(entry.value);
      }
    }
    if (phones.some(phonesMatch)) contactsById.set(contact.id, contact);
  }
}

const contacts = [...contactsById.values()];
const leadIds = [];

for (const contact of contacts) {
  for (const lead of contact._embedded?.leads ?? []) {
    if (lead && lead.id && !leadIds.includes(lead.id)) leadIds.push(lead.id);
  }
}

return [{
  json: {
    phone: first.phone,
    userId: first.userId,
    userName: first.userName,
    contactCount: contacts.length,
    contactName: contacts[0]?.name ?? '',
    contactIds: contacts.map((contact) => contact.id),
    contacts: contacts.map((contact) => ({ id: contact.id, name: contact.name ?? '' })),
    leadIds,
  },
}];

// =============================================================
// UNYX · Verificar Cliente — Nodo "Consolidar"
// Junta los datos del contacto con los nombres de los usuarios y con las
// constantes del cliente de esta rama (subdominio y pipelines excluidos).
//
// No consulta pipelines ni etapas: la regla de atención activa se basa en
// closed_at (ver _comun.js).
// =============================================================
const base = $('Meditec · Unificar Contactos').first().json;

const userMap = {};
try {
  const users = $('Meditec · Usuarios Kommo').first().json?._embedded?.users ?? [];
  for (const user of users) userMap[user.id] = user.name;
} catch (error) {
  // Sin permisos de administrador la lista de usuarios puede fallar:
  // se degrada a mostrar solo los ids.
}

return [{
  json: {
    ...base,
    subdomain: 'meditecec',
    pipelinesExcluidos: [],
    userMap,
  },
}];

// =============================================================
// UNYX · Verificar Cliente — Reglas compartidas
// Este archivo NO se ejecuta solo: build.js lo antepone a los nodos que
// evalúan leads, para que la regla de "atención activa" viva en un solo lugar.
//
// REGLA: un lead está ACTIVO si no tiene closed_at.
// Kommo marca closed_at cuando el lead se cierra (ganado o perdido) y lo
// limpia si se reabre. Por eso no hace falta consultar pipelines ni etapas:
// la regla funciona igual en cualquier cuenta y en cualquier pipeline.
// =============================================================

function unyxIsActive(lead, data) {
  if (!lead || lead.is_deleted) return false;
  if (data && (data.pipelinesExcluidos || []).includes(lead.pipeline_id)) return false;
  return !lead.closed_at;
}

function unyxDecorate(lead, data) {
  return {
    id: lead.id,
    name: lead.name || '#' + lead.id,
    created_at: lead.created_at || 0,
    responsible_user_id: lead.responsible_user_id || 0,
    responsibleName: data.userMap[lead.responsible_user_id] || '',
    leadUrl: 'https://' + data.subdomain + '.kommo.com/leads/' + lead.id,
  };
}

// Devuelve solo las atenciones activas, de la más reciente a la más antigua.
function unyxActiveLeads(leads, data) {
  return (leads || [])
    .filter((lead) => unyxIsActive(lead, data))
    .map((lead) => unyxDecorate(lead, data))
    .sort((a, b) => b.created_at - a.created_at);
}

function unyxClosedCount(leads, data) {
  const excluded = (data && data.pipelinesExcluidos) || [];
  return (leads || []).filter(
    (lead) => lead && !lead.is_deleted && !excluded.includes(lead.pipeline_id) && lead.closed_at
  ).length;
}

// Regla de decisión compartida por los dos workflows.
function unyxResolveState(active, userId) {
  if (active.length > 1) return { state: 'multiple_leads', activeLead: null };
  if (active.length === 1) {
    return {
      state: active[0].responsible_user_id === userId ? 'same_agent' : 'other_agent',
      activeLead: active[0],
    };
  }
  return { state: 'available', activeLead: null };
}

// =============================================================
// UNYX · Verificar Cliente — Nodo "Evaluar Atención" (workflow: verificar)
// Determina el estado y arma la respuesta que consume el widget.
// Requiere las reglas compartidas (_comun.js), que build.js antepone.
// =============================================================
const data = $('Meditec · Consolidar').first().json;
const leads = $('Meditec · Obtener Leads').first().json?._embedded?.leads ?? [];

const active = unyxActiveLeads(leads, data);
const resolved = unyxResolveState(active, data.userId);

return [{
  json: {
    ok: true,
    state: resolved.state,
    phone: data.phone,
    contactName: data.contactName,
    contactCount: data.contactCount,
    closedLeadCount: unyxClosedCount(leads, data),
    activeLead: resolved.activeLead,
    leads: resolved.state === 'multiple_leads' ? active : [],
  },
}];

// =============================================================
// UNYX · Verificar Cliente — Nodo "Sin Leads Activos" (workflow: verificar)
// Respuesta cuando el contacto no tiene ningún lead enlazado.
// =============================================================
const data = $('Meditec · Consolidar').first().json;

