const resolved = unyxResolveState(active, data.userId);

return [{
  json: {
    ok: true,
    state: resolved.state,
    phone: data.phone,
    contactName: data.contactName,
    contactCount: data.contactCount,
    closedLeadCount: unyxClosedCount(leads, data),
    activeLead: resolved.activeLead,
    leads: resolved.state === 'multiple_leads' ? active : [],
  },
}];

// =============================================================
// UNYX · Verificar Cliente — Nodo "Sin Leads Activos" (workflow: verificar)
// Respuesta cuando el contacto no tiene ningún lead enlazado.
// =============================================================
const data = $('LuxViajes · Consolidar').first().json;

return [{
  json: {
    ok: true,
    state: 'available',
    phone: data.phone,
    contactName: data.contactName,
    contactCount: data.contactCount,
    closedLeadCount: 0,
    activeLead: null,
    leads: [],
  },
}];
